def get_divisors(n):
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i*i != n:
                divs.append(n // i)
    return sorted(divs)

def check_candidate(n):
    divisors = get_divisors(n)
    tau_n = len(divisors)

    if tau_n < 5:
        return False, "Tau(n) < 5"

    # a, b, c are the 2nd, 3rd, and 5th smallest divisors
    if len(divisors) < 5:
        # Should not happen if tau_n >= 5, but safety check
        return False, "Fewer than 5 divisors"

    a = divisors[1]
    b = divisors[2]
    c = divisors[4]

    # Equation: (a + b + c)^2 = a^2 + b^2 + c^2 + 2n
    lhs = (a + b + c)**2
    rhs = a**2 + b**2 + c**2 + 2*n

    if lhs == rhs:
        return True, tau_n
    else:
        return False, "Equation failed"

# Test n=56 (Expected tau=8)
success_56, result_56 = check_candidate(56)
print(f"Testing n=56: Success={success_56}, Result={result_56}")

